from solution import sum_even_and_even_index


def test_issue_example():
    """Example: sum_even_and_even_index([5, 6, 12, 1, 18, 8],6) == 30."""
    assert sum_even_and_even_index([5, 6, 12, 1, 18, 8], 6) == 30  # 12 + 18 = 30


def test_issue_all_qualify():
    """Sum of even numbers at even positions includes every qualifying element."""
    assert sum_even_and_even_index([2, 1, 4, 1, 6], 5) == 12  # 2 + 4 + 6 = 12


def test_issue_odd_values_skipped():
    """Sum of even numbers at even positions skips odd values at even indices."""
    assert sum_even_and_even_index([1, 2, 3, 4, 5], 5) == 0  # 1, 3, 5 odd => 0


def test_issue_even_at_odd_index_skipped():
    """Sum of even numbers at even positions skips even values at odd indices."""
    assert sum_even_and_even_index([1, 2, 3, 4], 4) == 0  # 1 + 3 odd, 2 and 4 at indices 1,3 ignored => 0


def test_issue_zero_based_indexing():
    """Sum of even numbers at even positions uses 0-based even indices."""
    assert sum_even_and_even_index([2, 4], 2) == 2  # 2 = 2, 4 at index 1 ignored


def test_issue_single_even():
    """Sum of even numbers at even positions of single even element is itself."""
    assert sum_even_and_even_index([8], 1) == 8  # 8 = 8


def test_issue_single_odd():
    """Sum of even numbers at even positions of single odd element is zero."""
    assert sum_even_and_even_index([7], 1) == 0  # 7 odd => 0


def test_contract_empty_returns_zero():
    """Sum of even numbers at even positions is 0 for empty input."""
    assert sum_even_and_even_index([], 0) == 0  # sum([]) = 0


def test_contract_zero_is_even():
    """Sum of even numbers at even positions counts zero as even."""
    assert sum_even_and_even_index([0, 1, 2, 3], 4) == 2  # 0 + 2 = 2


def test_contract_negative_evens():
    """Sum of even numbers at even positions includes negative evens."""
    assert sum_even_and_even_index([-2, 99, -4, 99], 4) == -6  # -2 + -4 = -6
